// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;
    __InvMutHandleStub dao;

    function setUp() public {
        dao = new __InvMutHandleStub();
        c = new FlashGovernanceArbiter(address(dao));
    }

    function testFuzz_property(address actor, address target, uint256 unlockTime) public {
        vm.assume(actor != address(0) && target != address(0));
        unlockTime = bound(unlockTime, 1, 10_000);

        // configure flash governance: configured == false so onlySuccessfulProposal passes
        c.configureFlashGovernance(address(dao), 100, unlockTime, false);

        // create a pending flash decision from the DAO itself (flashEnabled allows DAO)
        vm.prank(address(dao));
        c.assertGovernanceApproved(actor, target, false);

        // advance time past the unlock time
        vm.warp(block.timestamp + unlockTime + 1);

        // after unlock, withdrawal must succeed and clear the decision
        vm.prank(actor);
        bool ok;
        try c.withdrawGovernanceAsset(target, address(dao)) {
            ok = true;
        } catch {
            ok = false;
        }

        (, uint256 amountAfter, , ) = c.pendingFlashDecision(target, actor);
        assertTrue(ok && amountAfter == 0, "withdrawal after unlock must succeed and clear decision");
    }
}
contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
